import{_ as e,o as r,c as l,a2 as i}from"./chunks/framework.DfDAiEgj.js";const t="/2bPM/img/operation_in_life_cycle.png",h="/2bPM/img/goal_fenjie.jpg",f=JSON.parse('{"title":"GTM（go to marketing）","description":"","frontmatter":{},"headers":[],"relativePath":"idea/GTM.md","filePath":"idea/GTM.md","lastUpdated":null}'),o={name:"idea/GTM.md"};function n(p,a,s,d,c,u){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="gtm-go-to-marketing" tabindex="-1">GTM（go to marketing） <a class="header-anchor" href="#gtm-go-to-marketing" aria-label="Permalink to &quot;GTM（go to marketing）&quot;">​</a></h1><p>市场推广、培训、成本核算。</p><h2 id="业绩相关" tabindex="-1">业绩相关 <a class="header-anchor" href="#业绩相关" aria-label="Permalink to &quot;业绩相关&quot;">​</a></h2><p>业绩体现包括：用户增长+核心路径转化提升+营收增长等。<a href="http://dadaghp.com/index/index/article_detail/id/670.html" target="_blank" rel="noreferrer">^13</a></p><p>业绩体现一定要量化，用具体的数字一是有说服力，尤其是应聘行业内的岗位，二是熟记数据可以体现对产品的关注程度，第三精准的数据阐述逻辑可以体现产品经理的数据分析能力。</p><p>通常来讲，产品营收=用户规模x转化率x单笔毛利-成本，我们再进行拆解 产品营收=（存量用户+新增用户x留存率）x转化率x单笔毛利-成本，由上面公式可见，要想提高产品营收那重要的就是提升新增用户数、用户留存率、转化率以及降低成本。</p><h2 id="产品运营-1" tabindex="-1">产品运营 <a href="https://baike.baidu.com/item/%E4%BA%A7%E5%93%81%E8%BF%90%E8%90%A5/1978562" target="_blank" rel="noreferrer">^1</a> <a class="header-anchor" href="#产品运营-1" aria-label="Permalink to &quot;产品运营 [^1]&quot;">​</a></h2><p>产品和运营原本就是不分家的，产品经理不考虑所负责功能的商业价值和经济效益，他的不可替代性就小。如果一个产品经理，不仅能够设计好的体验，还能设计好的在运营上可以提供支持的功能，同时还可以通过数据来推进迭代、驱动运营方案，那这样的产品经理就是非常珍稀了。<a href="https://www.zhihu.com/question/27283535/answer/80493189" target="_blank" rel="noreferrer">^33</a></p><h3 id="了解运营的目的-3" tabindex="-1">了解运营的目的 <a href="https://www.zhihu.com/pub/reader/119980992/chapter/1284104607329615872" target="_blank" rel="noreferrer">^3</a> <a class="header-anchor" href="#了解运营的目的-3" aria-label="Permalink to &quot;了解运营的目的 [^3]&quot;">​</a></h3><p>为了让产品经理除了单纯地进行产品功能优化，还要思考如何让更多的用户来使用产品，只有让更多的用户使用了产品，产品才能实现更好的自我优化</p><p>产品的本质是解决用户的痛点，而运营的本质是通过各种<strong>方法和渠道把产品的价值传递给用户</strong>。</p><ul><li>产品用户如何获取</li><li>产品用户如何维系</li><li>产品如何获取收入<a href="https://www.zhihu.com/zvideo/1421162477229404160" target="_blank" rel="noreferrer">^40</a></li></ul><h3 id="在生命周期中的作用" tabindex="-1">在生命周期中的作用 <a class="header-anchor" href="#在生命周期中的作用" aria-label="Permalink to &quot;在生命周期中的作用&quot;">​</a></h3><p><img src="'+t+'" alt="运营在生命周期中的作用^14"></p><h3 id="产品与运营的关系" tabindex="-1">产品与运营的关系 <a class="header-anchor" href="#产品与运营的关系" aria-label="Permalink to &quot;产品与运营的关系&quot;">​</a></h3><p>产品经理主要是负责产品设计阶段的工作，运营是负责产品推广的工作，把产品当成一个孩子来看，产品设计阶段就是“生孩子”，产品推广阶段就是“把孩子养大，而且还必须养好”。</p><p>产品设计阶段主要是界定并为用户提供长期价值，在运营阶段主要是完善产品长期价值，并提供给用户短期价值。</p><p>很多产品的长期价值往往用户一时半会儿感知不到，需要运营创造一些短期价值去刺激用户使用和体验，并根据用户的持续反馈调整、迭代、优化来完善长期价值。</p><p>四驾马车:内容、用户、活动、社区<a href="https://mp.weixin.qq.com/s?__biz=MzAxNjMyMDUzMQ==&amp;mid=2247494223&amp;idx=2&amp;sn=0528f065f77307519fe33caf2f852f22&amp;chksm=9bf43b33ac83b2255e3f1091f8d3bf5e415bf8198fd94b218e5f47343eaa4e158e52d6620c91&amp;scene=21#wechat_redirect" target="_blank" rel="noreferrer">^15</a></p><p>类目运营<a href="https://zhuanlan.zhihu.com/p/38808105" target="_blank" rel="noreferrer">^37</a>：类目经理负责电子商务网站的类目结构<a href="https://baike.baidu.com/item/%E7%B1%BB%E7%9B%AE%E8%BF%90%E8%90%A5/8881199" target="_blank" rel="noreferrer">^38</a></p><h3 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>运营相当于一个保姆，是一项从内容建设，用户维护，活动策划三个层面来管理产品内容和用户的职业。</p><ol><li>内容建设：建立标准，挽留、裂变：防止劣质的内容驱逐优质的用户</li><li>用户维护：挽留：建立完善Q&amp;A机制，解决用户投诉和困难；拉新：主动邀请有价值的用户来使用产品。</li><li>活动策划：煽动用户互动，加强产品品牌。产品运营最接近用户，需求质量高。</li></ol><h3 id="工作内容-2" tabindex="-1">工作内容 <a href="https://www.zhihu.com/pub/reader/119911878/chapter/1283841129226715136" target="_blank" rel="noreferrer">^2</a> <a class="header-anchor" href="#工作内容-2" aria-label="Permalink to &quot;工作内容 [^2]&quot;">​</a></h3><p>从内容编辑、SEO 优化、产品推广、SEM、活动运营、社群运营、BD 合作等基本版块到整体统筹独立负责 APP 社区体系搭建</p><h3 id="种子期-关注留存率" tabindex="-1">种子期:关注留存率 <a class="header-anchor" href="#种子期-关注留存率" aria-label="Permalink to &quot;种子期:关注留存率&quot;">​</a></h3><p>关注自然留存率:</p><ul><li>留存率好——核心功能被认可用户群体是否有偏差</li><li>留存率不好——产品核心功能不明确</li></ul><h4 id="种子用户特点" tabindex="-1">种子用户特点 <a class="header-anchor" href="#种子用户特点" aria-label="Permalink to &quot;种子用户特点&quot;">​</a></h4><ul><li>强需求</li><li>核心功能敏感</li><li>愿意尝试使用并传播</li></ul><h4 id="启动法" tabindex="-1">启动法 <a class="header-anchor" href="#启动法" aria-label="Permalink to &quot;启动法&quot;">​</a></h4><ul><li>事件法:试用为内容型产品地推法:</li><li>020产品:坚持坚决的执行地推</li><li>马甲法:社交产品，运营横仿用户发</li><li>传染法:基于特定的用户群兴趣点进行关系链传播</li></ul><h3 id="爆发期-提高来源量" tabindex="-1">爆发期:提高来源量 <a class="header-anchor" href="#爆发期-提高来源量" aria-label="Permalink to &quot;爆发期:提高来源量&quot;">​</a></h3><p>产品:完善产品核心功能，暂时不要新功能</p><p>外延做深种子群体扩大范围推广传播</p><p>运营目标:拉来更多的用户，来源量（一个产品定位越精确，推广的难度就越低。）</p><ul><li><p>做深种子群体扩大范围推广传插</p></li><li><p>做广跨领域或行业展开推广</p></li><li><p>买\\培养流量:培养网络红人，打广告；推广和流量获取，了解 SEO、ASO<a href="https://www.zhihu.com/question/20497883/answer/2106365660" target="_blank" rel="noreferrer">^36</a></p></li><li><p>傍大款:与大平台合作，例如从酷6看网络运营度贴吧合作<a href="https://www.jianshu.com/p/b62409f10470" target="_blank" rel="noreferrer">^9</a></p></li><li><p>靠关系:通过关系链网络化传播</p></li><li><p>装有钱:运营资金雄厚(补贴，激励方式)，目标是拉来更多的用户</p></li><li><p>共同富裕:与上传视频者共享广告利益</p></li><li><p>导流：游戏依靠QQ微信的周边。</p></li></ul><h4 id="平台期活跃度" tabindex="-1">平台期活跃度 <a class="header-anchor" href="#平台期活跃度" aria-label="Permalink to &quot;平台期活跃度&quot;">​</a></h4><p>平台期是为了下个爆发期而做的运营准备</p><p>产品:提高<a href="https://blog.csdn.net/lanxingfeifei/article/details/89843332" target="_blank" rel="noreferrer">用户体验</a>，考虑系统架构是否能够继续支持下一轮爆发性增长</p><ul><li>举办活动</li><li>用户等级</li><li>新功能拉动 <a href="https://pic4.zhimg.com/v2-670698cb727b90e20895360b2fe85ea8_r.jpg?source=1940ef5c" target="_blank" rel="noreferrer">^8</a></li></ul><h3 id="好文案" tabindex="-1">好文案 <a class="header-anchor" href="#好文案" aria-label="Permalink to &quot;好文案&quot;">​</a></h3><p>终极文案不是突出产品优势和品牌，而是唤起消费者的消费冲动。触达用户之前都需要做用户筛选，尽量做到精准触达。平台一般有三种方式触达用户：短信、站内信、Push（APP弹窗）。<a href="https://www.zhihu.com/question/46954878/answer/2096480336" target="_blank" rel="noreferrer">^35</a></p><p>更多：</p><ul><li><a href="https://zhuanlan.zhihu.com/p/93474666" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/93474666</a></li></ul><h3 id="next方法-5" tabindex="-1">NEXT方法 <a href="http://www.changgpm.com/" target="_blank" rel="noreferrer">^5</a> <a class="header-anchor" href="#next方法-5" aria-label="Permalink to &quot;NEXT方法 [^5]&quot;">​</a></h3><ul><li>N(NEW)：做出了 （New）新的产品价值（WHY）</li><li>E(Expolsive)：无法脱颖而出的产品，其实是因为做得还不够极致。</li><li>X(XENOGENEIC)：必须走出MRD，多做田野调查，多与用户面对面交流。</li><li>T(TALENT)：越用这些产品用户越觉得这些产品懂自己。</li></ul><h3 id="体系的建立" tabindex="-1">体系的建立 <a class="header-anchor" href="#体系的建立" aria-label="Permalink to &quot;体系的建立&quot;">​</a></h3><p>比如天猫京东等电商平台为了让商家在618和双11中更好的准备打折促销活动，会在大促之前发布商家作战地图，商家作战地图纵向涵盖了商家所有的活动，比如推广、视觉、商品、社交、内容、用户等，时间跨度包含了筹备期、蓄水期、预热期 、售卖期 、爆发期、返场期、总结复盘等。</p><p>运营模型的整理的关键来自于用户的关键行为，比如上图中我们思考的用户从哪里来（线上和线下），用户如何认知我们（认知），如何让用户进店（进店），用户进店之后怎么转化（购买），用户怎么沉淀下来（社群），以及最后如何让用户给我们的产品做自传播（传播）。</p><h4 id="指标确认" tabindex="-1">指标确认 <a class="header-anchor" href="#指标确认" aria-label="Permalink to &quot;指标确认&quot;">​</a></h4><p>在互联网中，运营指标指的是需要成功完成活动的数据指标，如电商运营中关于流量性的指标独立访客数（UV）、页面访问数（PV）、成交金额（GMV）、销售金额等。</p><p>而工具类产品的核心指标是用户体验。算法工程师其实存在一个比较大的困惑，如何用数据去度量用户体验这个比较虚的目标。最常用的一个度量指标就是用户净推荐值，具体来讲就是去问用户“你是否愿意将这个产品推荐给你的朋友或者同事”。</p><p>更进一步，我们可以设置一个北极星指标，例如产品日活，然后结合每个模块进行细致拆分。我们可能需要关注每日新增用户，核心用户在今天的贡献数值，打开率，使用频次，目标达成率，分享率等等。当我们把这些核心目标真正拆解清楚的时候，我们就有了主要指标，就是我们应该怎么样去把这个产品做好。</p><p>MySpace公司运营的主要指标是注册“用户数”，而Facebook在Mark的指引下，在成立的早期就把“月活跃用户数”作为对外汇报和内部运营的主要指标。<a href="http://www.woshipm.com/data-analysis/454520.html" target="_blank" rel="noreferrer">^16</a></p><p><img src="'+h+'" alt="核心目标的拆解"></p><h4 id="模块划分" tabindex="-1">模块划分 <a class="header-anchor" href="#模块划分" aria-label="Permalink to &quot;模块划分&quot;">​</a></h4><p>为了达到运营活动的运营效果需要把整个运营活动按职能进行拆分。比如常见的运营职能有内容运营、数据运营、活动运营、用户运营、渠道运营、市场运营、会员运营、社群运营、商家运营等。</p><h3 id="aso" tabindex="-1">ASO <a class="header-anchor" href="#aso" aria-label="Permalink to &quot;ASO&quot;">​</a></h3><p>应用商店优化(ASO)是指提高应用或游戏在应用商店中的曝光度，以提高应用的自然下载量为目标的过程。当应用在各种搜索条件中排名靠前，在排行榜中保持较高的位置，或在应用商店中获得推荐时，它们就更容易被发现。</p><h3 id="ai产品的运营-6" tabindex="-1">AI产品的运营 [6] <a class="header-anchor" href="#ai产品的运营-6" aria-label="Permalink to &quot;AI产品的运营 [6]&quot;">​</a></h3><p>上线、包装、宣传，产品经理尽量评估产品的商业化和产品化效果，动态调整算法模型的研发投入量。</p><h2 id="增长" tabindex="-1">增长 <a class="header-anchor" href="#增长" aria-label="Permalink to &quot;增长&quot;">​</a></h2><p>3 年 3 款产品百万级增长方法论 - 腾讯技术工程的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/397810603" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/397810603</a></p><h2 id="营销" tabindex="-1">营销 <a class="header-anchor" href="#营销" aria-label="Permalink to &quot;营销&quot;">​</a></h2><p>根据目标用户、产品特点及品牌塑造需要，进行营销及公关策略的制定和执行，以实现有效传播、危机化解、产品目标达成。<a href="https://t.qidianla.com/1175149.html" target="_blank" rel="noreferrer">^12</a>露华浓公司创始人查尔斯·雷夫森说：“我们的工厂生产唇膏，我们的广告贩售希望”。<a href="https://zhuanlan.zhihu.com/p/79795210" target="_blank" rel="noreferrer">^34</a></p><p>推荐书籍《定位》《流量池》《运营之光》《增长黑客》《参与感》《消费者行为学》）《爆款文案》<a href="http://www.woshipm.com/pmd/3024508.html" target="_blank" rel="noreferrer">^10</a></p><h3 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h3><p>在信息海量传播的情况下，人的心智就像一道屏障，对信息进行筛选，将大部分信息拒之门外。一般来说，大脑只会接受与先前的知识、经验相吻合的信息。定位概念最重要的原则之一就是不要试图改变人们的心智。</p><p>身处过度传播的社会，营销方最好的应对方法是将信息极度简化。信息必须避免含混不清、模棱两可，足够简化的信息才有可能楔进潜在顾客的大脑。</p><p>信息只有极小的一部分能被潜在顾客接收，营销方应把精力集中在潜在顾客的看法上。</p><p>在这个信息传播的丛林中，要想有所收获，只能有所选择，减少目标，集中精力，细分市场。一言以蔽之，就是要定位。</p><p>定位就是要弄清楚潜在顾客的认知，这个可以通过学习心理学解决。然后结合顾客心智的空白和产品自身的特点，挖掘出来一个精简的产品故事，在潜在顾客面前不断曝光这个产品故事，十年如一日，最后将这个产品故事楔入潜在顾客心智的空白处。<a href="https://mp.weixin.qq.com/s/O95ctf274-uJUxU7Kwd6vQ" target="_blank" rel="noreferrer">^32</a></p><h3 id="营销很好-没有盈利" tabindex="-1">营销很好，没有盈利 <a class="header-anchor" href="#营销很好-没有盈利" aria-label="Permalink to &quot;营销很好，没有盈利&quot;">​</a></h3><ol><li>提高用户量；</li><li>客单价（用户价值）；</li><li>成本管理；</li><li>增加资产的周转率；</li><li>寻找“增长杠杆”。</li></ol><h3 id="饥饿营销" tabindex="-1">饥饿营销 <a class="header-anchor" href="#饥饿营销" aria-label="Permalink to &quot;饥饿营销&quot;">​</a></h3><p>真正目的不是为了利润，而是为了品牌附加值。</p><p>前提：</p><ol><li>产品具备不可替代性</li><li>消费者心智不成熟</li><li>市场竞争不激烈。</li></ol><p>副作用：</p><ol><li>客户流失。过度饥饿营销，就是将客户“送”给竞争对手。</li><li>顾客反感。过度饥饿营销，会让消费者饿到冷静，觉得被愚弄，对品牌产生厌恶。</li></ol><p>反制：既然数量有限，我就把机会让给更需要的人吧<a href="https://space.bilibili.com/10330740/dynamic?spm_id_from=444.41.0.0" target="_blank" rel="noreferrer">^44</a></p><h3 id="互动营销mind方法论" tabindex="-1">互动营销MIND方法论 <a class="header-anchor" href="#互动营销mind方法论" aria-label="Permalink to &quot;互动营销MIND方法论&quot;">​</a></h3><ol><li>M（Measurability）：用可衡量的效果体现在线营销的有效性、可持续性以及科学性。</li><li>I（Interactive Experience）：用互动式的体验提供高质量的创新体验和妙趣横生的网络生活感受。</li><li>N（Navigation）：用精确化的导航保障目标用户的精准选择和在线营销体验的效果。</li><li>D（Differentiation）：用差异化的定位创造在线营销的不同，满足客户独特性的需求。</li></ol><h3 id="more" tabindex="-1">More <a class="header-anchor" href="#more" aria-label="Permalink to &quot;More&quot;">​</a></h3><p><a href="https://www.niaogebiji.com/" target="_blank" rel="noreferrer">https://www.niaogebiji.com/</a></p><h2 id="市场营销" tabindex="-1">市场营销 <a class="header-anchor" href="#市场营销" aria-label="Permalink to &quot;市场营销&quot;">​</a></h2><p>财务部门是一个独立部门，而市场营销不是，市场营销是需要你的公司全体员工一年365天一周7天、一天24小时时时刻刻要去做的工作。<a href="http://www.tanmer.com/thought/290" target="_blank" rel="noreferrer">^19</a></p><p>人不能不交流，同理，人也不能不去做营销工作：</p><p>每次你接打电话，就是市场营销。 每次你发出一封邮件，就是市场营销。 每次有人使用你的产品，就是市场营销。 你在网站上发表的每篇文章，都是市场营销。 你每次在网络上的分享点赞任何行为，都是市场营销。</p><h3 id="市场" tabindex="-1">市场 <a class="header-anchor" href="#市场" aria-label="Permalink to &quot;市场&quot;">​</a></h3><p>市场人员更有“战略”眼光，这容易看到未来，而活不好今天。<a href="https://www.zhihu.com/question/21648437/answer/1591831612" target="_blank" rel="noreferrer">^21</a></p><p>marketing 首先是一个永远在花钱的部门，而且还是一个“永远不知道有一半钱花在了哪里”的部门。同时，marketing在花钱之后，到底给销售带来了多少增长？给品牌带来了多少正面的影响？在消费者心中留下多深的印象？都很难评估。<a href="https://www.zhihu.com/question/21648437/answer/133050815" target="_blank" rel="noreferrer">^20</a></p><p>市场有一个“儿子”叫广告。他们还有一个特别好的兄弟就是专门给他们擦屁股的叫公关<a href="https://zhuanlan.zhihu.com/p/22792840" target="_blank" rel="noreferrer">^25</a></p><h4 id="广告" tabindex="-1">广告 <a class="header-anchor" href="#广告" aria-label="Permalink to &quot;广告&quot;">​</a></h4><p>在Advertising, PR, Promotion领域的职位，如果对此方面感兴趣，可以考虑具体学习Marketing下Advertising方向的细分</p><p>此类课程设置中会大量出现Marketing Communications；Advertising；Media Planning and Strategy；Public Relations and Corporate Communications这一类的课程。<a href="https://zhuanlan.zhihu.com/p/47896965" target="_blank" rel="noreferrer">^26</a></p><p>浅析互联网广告<a href="https://blog.csdn.net/acelit/article/details/77902460" target="_blank" rel="noreferrer">^27</a></p><p>广告收入 = PV * CTR * price（点击），这时候，我们知道，要想提升收入，可以去提示广告的展示量，引入更多的广告场景提升PV，或者优化广告样式和文案即提升广告点击率，又或者对接更优质的广告主以提升广告点击的单价。如果是面向用户型产品，假如我们需要提升产品的活跃DAU，需要怎样的一种思路？这个问题就相对复杂些，但并不是无迹可寻。这时候，我们可以这么来分析，产品的用户分为新用户，留存用户（活跃和不活跃），流失用户。这时候，我们提升产品活跃DAU的方法可以围绕着这四大方面进行分析。对于新用户，通过分析新用户来源的各个流程的转化率逐个提升，通过ASO（或SEO）提升产品的搜索排名；针对留存用户，则分析用户反馈和用户的行为日志，找出产品核心的价值和用户痛点（这个很难，但非常重要）提升产品价值，或者策划一些运营功能活动，提升非活跃的留存用户，让他们从安装的用户变成真正的活跃用户；针对走失的用户，则分析为什么走失，如何设置挽留方案，使得这批用户回流。那么经过这样的一层层分析<a href="https://zhuanlan.zhihu.com/p/31463327" target="_blank" rel="noreferrer">^28</a></p><p>如何吸引到更多用户。<a href="https://zhuanlan.zhihu.com/p/393916722" target="_blank" rel="noreferrer">^29</a></p><ol><li>设计出独特卖点，看文案的水平了</li><li>获取用户的渠道：地推、广告、导流、ASO\\SEO、社会化分享、软文、论坛、IM\\SNS推广、微信公众号营销、微博营销、口碑传播。</li><li>如何跨越鸿沟，打动理性用户。</li></ol><ul><li>单点突破以点带面：先把点满足到最好，满足到极致，通过该店吸引到用户，然后逐渐扩大。</li><li>用户有需要，但是短时间很难接受满足方式，可以采用促销让用户先低成本体验一把。比如京东，很多书本是亏本再卖，就是为了让用户体验京东的快递服务。</li><li>放大用户心中的情感。</li><li>让用户意识到问题，比如卖儿童安全座椅的，就报道一些儿童安全座椅质量不好导致的孩子受伤事件。</li><li>用户有欲望，但是欲望不强。利用一些人性的弱点强化欲望，比如淘宝创造的双十一活动。</li><li>如果你一开始很难吸引到用户，看能否寻找其他切入点，曲线救国。比如大姨妈月经记录，再推出卫生等其他女性用品来盈利。</li></ul><h4 id="公关媒体" tabindex="-1">公关媒体 <a class="header-anchor" href="#公关媒体" aria-label="Permalink to &quot;公关媒体&quot;">​</a></h4><p>游戏公司：路演宣传、代言人商谈、玩家舆情疏导、活动策划<a href="https://www.bilibili.com/video/BV1u34y1X7PC?spm_id_from=444.41.0.0" target="_blank" rel="noreferrer">^39</a></p><h3 id="增长战略" tabindex="-1">增长战略 <a class="header-anchor" href="#增长战略" aria-label="Permalink to &quot;增长战略&quot;">​</a></h3><p><a href="http://www.woshipm.com/operate/4101930.html" target="_blank" rel="noreferrer">http://www.woshipm.com/operate/4101930.html</a></p><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1><h2 id="bd" tabindex="-1">BD <a class="header-anchor" href="#bd" aria-label="Permalink to &quot;BD&quot;">​</a></h2><p>商务拓展，英文为Business Development，缩写BD，翻译成中文就是商务拓展。BD职业广泛存在于IT与电信增值行业中。“BD”的定义是： 根据公司战略，连接并推动上游及平行的合作伙伴结成利益相关体，和相关政府、媒体、社群等组织及个人寻求支持并争取资源。“BD”可以理解为“广义的Marketing”，或者是“战略 Marketing” 。BD延伸了企业组织和利益的边界，BD部门的领导首先要具有宏观的战略思维。</p><h2 id="培训" tabindex="-1">培训 <a class="header-anchor" href="#培训" aria-label="Permalink to &quot;培训&quot;">​</a></h2><h2 id="成本核算" tabindex="-1">成本核算 <a class="header-anchor" href="#成本核算" aria-label="Permalink to &quot;成本核算&quot;">​</a></h2><h2 id="销售" tabindex="-1">销售 <a class="header-anchor" href="#销售" aria-label="Permalink to &quot;销售&quot;">​</a></h2><p>一个完整的销售流程应当至少包括售前服务、售中服务和售后服务三个部分。在当前市场环境下，售后服务被放到特别突出的位置，很少有人研究分析销售中的售前服务问题。在整个营销和销售系统链条中，售前服务是营销和销售之间的纽带，作用至关重要，不可忽视。+售前服务是企业在顾客未接触产品之前所开展的一系列刺激顾客购买欲望的服务工作。售前服务的内容多种多样，主要是提供信息、市场凋查预测、产品定制、加工整理、提供咨询、接受电话订货和邮购、提供多种方便和财务服务等。售前服务的主要目的是协助客户做好工程规划和系统需求分析，使得我们的产品能够最大限度的满足用户需要，同时也使客户的投资发挥出最大的综合经济效益。&amp;rlz=1C1GCEA_enJP909HK909&amp;oq=一个完整的销售流程应当至少包括售前服务、售中服务和售后服务三个部分。在当前市场环境下，售后服务被放到特别突出的位置，很少有人研究分析销售中的售前服务问题。在整个营销和销售系统链条中，售前服务是营销和销售之间的纽带，作用至关重要，不可忽视。++%E3%80%80%E3%80%80售前服务是企业在顾客未接触产品之前所开展的一系列刺激顾客购买欲望的服务工作。售前服务的内容多种多样，主要是提供信息、市场凋查预测、产品定制、加工整理、提供咨询、接受电话订货和邮购、提供多种方便和财务服务等。售前服务的主要目的是协助客户做好工程规划和系统需求分析，使得我们的产品能够最大限度的满足用户需要，同时也使客户的投资发挥出最大的综合经济效益。<a href="https://wiki.mbalib.com/wiki/%E5%94%AE%E5%89%8D%E6%9C%8D%E5%8A%A1" target="_blank" rel="noreferrer">^42</a></p><p>推销、营销和销售对比：推销就是忽略客户需求；销售呢，叫作满足客户需求；营销，叫作创造客户需求。<a href="https://www.zhihu.com/question/19663849/answer/617212211" target="_blank" rel="noreferrer">^43</a></p><h3 id="售前服务" tabindex="-1">售前服务 <a class="header-anchor" href="#售前服务" aria-label="Permalink to &quot;售前服务&quot;">​</a></h3><p>现在IT公司都经历了原来的产品型到解决方案型，再到IT服务型企业过渡的一种转变时期，记得在96年做IT销售的时候，没有售前工程师这个职务，大小事情都自己做主，于是出现了一些非常不规范的事情，一个销售可以信口开河地承诺任何事情，包括产品性能、服务、价格等等。其实呢，一个销售的目的就是卖产品，哪管其他的，于是导致了销售的口碑不好</p><p>售前工程师是指专门来负责对用户需求提供建议或帮助用户给出一套解决方案，以促进销售达成的一个专业职务。</p><p>过去，厂家是上帝，厂家给你什么产品就是什么产品，你就该怎么用，现在是用户提出需求，你来解决，不知不觉我们来到了解决方案的时代。<a href="https://baike.baidu.com/item/%E5%94%AE%E5%89%8D%E5%B7%A5%E7%A8%8B%E5%B8%88/9341955" target="_blank" rel="noreferrer">^41</a></p><h3 id="销售服务" tabindex="-1">销售服务 <a class="header-anchor" href="#销售服务" aria-label="Permalink to &quot;销售服务&quot;">​</a></h3><p>典型的销售漏斗图（Sales Funnel）[31]</p><p>• 潜在客户（Prospects）：让客户知道你的企业、产品，成为企业的潜在客户 • 接触客户（Contacts）：与客户进行初步沟通 • 后续洽谈（Follow-ups）：跟进，继续与客户洽谈 • 提案/报价（Proposal/Offer）：发送方案/报价/合同 • 赢得/关闭（Sales/Close）</p><p>需要永远把客户的利益放在第一位，尽全力帮助客户成功。思考如果你是客户，你想要什么样的方案？</p><p>销售人员接“地气”，他们离“成交”最近。[21] 我卖出去多少产品，收获了多少个客户，维护了多少条渠道，所得到的利润和回报都是数据化，可视化的。[20]</p><ul><li>销售经历体会过哪怕签了合同也放不下心茶饭不思，因为钱没全部到手，就不算真正的成交；</li><li>销售经历过跟了半年的单被以前称兄道弟的同学切走被背叛却又骂不出口的无奈；</li><li>销售经历过一杯2两白酒一万订单，体会过你拿钱砸我左脸我得把右脸给你砸；</li><li>销售经历过哪怕你今天是大中华区经理，一个大单败给了对手，明天你就拍拍屁股走人的潜规则；</li><li>销售经历过为了成交陪阿姨级别的客户聊天吃饭，陪大肚子老大爷说文人书法；</li><li>销售经历过被当枪使，经历过兔死狗烹，经历过刚熟悉一个区域就因为老总的怀疑而被调去鸟不拉屎的地方，因为销售经历过你若盛开一次别人就不断地逼你盛开，甚至你自己，都无法面对曾经的辉煌。[18]</li></ul><p>IBM这样的公司干得很好，它们进行创新，成为或接近成为某个领域的垄断者，然后产品的质量就变得不那么重要了。这些公司开始重视优秀的销售人员，因为是他们在推动销售、改写了收入数字，而不是产品的工程师和设计师。因此销售人员最后成为公司的经营者。IBM的约翰·埃克斯是聪明、善辩、非常棒的销售人员，但是对产品一无所知。同样的事情也发生在施乐。做销售的人经营公司，做产品的人就不再那么重要，其中很多人就失去了创造的激情。[22]</p><h3 id="售后服务" tabindex="-1">售后服务 <a class="header-anchor" href="#售后服务" aria-label="Permalink to &quot;售后服务&quot;">​</a></h3><p>昨天的钱，是你已经收到的钱。但是很多时候你收到了钱，还没有向客户交付对等的服务。</p><p>在公司里，支持和服务部门负责赚昨天的钱。</p><p>对应到具体的岗位，就是售后、技术支持工程师等。客服类主要有客服代表、客服主管、客服经理，主要是销售业务后续的维护与沟通。<a href="https://www.zhihu.com/question/428821980/answer/1560134840" target="_blank" rel="noreferrer">^24</a></p><p>比如很多IT公司，卖出去设备、软件之后，还需要提供一两年的免费服务。</p><p>想要赚好昨天的钱，就要不断思考：</p><ul><li>卖出去的产品，有没有用户投诉？</li><li>承诺过的服务，有没有完全交付？</li><li>用户提的需求，有没有很好响应？</li></ul>',132)])])}const m=e(o,[["render",n]]);export{f as __pageData,m as default};
